testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { rodarComando, resumirResultado } from './solution.mjs';

test('rodarComando devolve o resultado do executor (sucesso)', async () => {
  const executor = {
    async rodar(comando) {
      return { codigo: 0, saida: 'v20.0.0' };
    },
  };
  assert.deepEqual(await rodarComando(executor, 'node --version'), { codigo: 0, saida: 'v20.0.0' });
});

test('rodarComando devolve o resultado de um comando que falhou', async () => {
  const executor = {
    async rodar(comando) {
      return { codigo: 1, saida: '', erro: 'comando não encontrado' };
    },
  };
  assert.equal((await rodarComando(executor, 'xyz')).codigo, 1);
});

test('resumirResultado interpreta o código de saída', () => {
  assert.equal(resumirResultado({ codigo: 0, saida: 'ok' }), 'sucesso');
  assert.equal(resumirResultado({ codigo: 1, saida: '' }), 'erro');
  assert.equal(resumirResultado({ codigo: 2, saida: '' }), 'erro');
});

test('lança erro em entradas inválidas', async () => {
  await assert.rejects(() => rodarComando({}, 'ls'), /rodar/);
  assert.throws(() => resumirResultado({ saida: 'oi' }), /código/);
});

solutionCode:
export async function rodarComando(executor, comando) {
  if (!executor || typeof executor.rodar !== 'function') {
    throw new Error('executor precisa ter uma função rodar');
  }
  return executor.rodar(comando);
}

export function resumirResultado(resultado) {
  if (!resultado || typeof resultado.codigo !== 'number') {
    throw new Error('resultado precisa ter um código de saída');
  }
  return resultado.codigo === 0 ? 'sucesso' : 'erro';
}
